<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Sample task update · Everbranch Enterprise</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f4f5ef;color:#243e32;font:15px/1.7 system-ui,sans-serif}header{padding:23px;background:#203f32;color:white}header strong{font:25px Georgia,serif}header small{display:block;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#d0dcc1}main{max-width:760px;margin:auto;padding:25px 16px}h1,h2{font-family:Georgia,serif;font-weight:400;line-height:1.3}h1{font-size:32px}h2{font-size:24px}.panel{background:white;border:1px solid #d7e1cd;padding:23px;border-radius:8px;margin-bottom:19px}.muted{font-size:13px;color:#62745b}.badge{display:inline-block;background:#eaf0df;border:1px solid #c9d5b8;padding:4px 9px;border-radius:4px;font-size:11px}dl{display:grid;grid-template-columns:125px minmax(0,1fr);gap:10px}dt{font-size:12px;color:#62745b}dd{margin:0;overflow-wrap:anywhere}label{display:block;font-size:13px;margin:14px 0}textarea,select,input,button{font:inherit}textarea,select,input{display:block;width:100%;padding:12px;border:1px solid #b9c8ad;border-radius:5px;margin-top:6px}button,a.button{display:inline-block;min-height:44px;padding:11px 16px;border:1px solid #b9c8ad;border-radius:5px;background:white;color:#294f3c;cursor:pointer;text-decoration:none}button.primary{background:#2c553d;border-color:#2c553d;color:white}button:disabled{opacity:.5;cursor:not-allowed}.actions{display:flex;flex-wrap:wrap;gap:10px}#status{min-height:24px;overflow-wrap:anywhere}.error{color:#963c30}.file{padding:14px 0;border-bottom:1px solid #e0e8d7}.file strong{overflow-wrap:anywhere}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #b18b2c;outline-offset:3px}[hidden]{display:none!important}@media(max-width:480px){main{padding:18px 12px}.panel{padding:19px}dl{grid-template-columns:1fr;gap:3px}dd{margin-bottom:9px}.actions button{flex:1}}
</style></head><body><header><strong>Everbranch</strong><small>Enterprise · Limited sample task link</small></header><main><span class="badge">FICTIONAL WORK · APPROVED DEMONSTRATION</span><h1>Keep the next step visible.</h1><p class="muted">This expiring link permits an acknowledgment, a sample update and limited evidence uploads. It grants no college account, mailbox access or other work access.</p><p id="status" role="status" aria-live="polite"></p><button id="refresh" type="button">Refresh current task</button>
<div id="content" hidden><section class="panel"><h2 id="title"></h2><dl id="details"></dl><p class="muted" id="expiry"></p><button id="acknowledge" type="button">Acknowledge this sample task</button><p class="muted" id="acknowledged"></p></section>
<section class="panel"><h2>Record a sample update</h2><form id="update-form"><label>Status<select id="task-status"><option value="in_progress">In progress</option><option value="awaiting_review">Awaiting review</option></select></label><label>Update note<textarea id="note" rows="4" maxlength="2000" placeholder="Describe the sample update. Do not enter private student or employee information."></textarea></label><div class="actions"><button class="primary" id="save-update">Save sample update</button><button id="retry-update" type="button" hidden>Retry the same interrupted update</button></div></form></section>
<section class="panel"><h2>Attach a photo or PDF</h2><p class="muted">One JPEG, PNG or PDF up to 5 MB per upload. Files stay private and unavailable to download until verified clean. If an upload is interrupted, select the same file and retry; its request key is retained.</p><form id="upload-form"><label>Photo or PDF<input id="file" type="file" accept="image/jpeg,image/png,application/pdf,.jpg,.jpeg,.png,.pdf" required></label><button id="upload-button" type="submit">Upload sample evidence</button></form><p id="upload-status" class="muted" role="status"></p><div id="files"></div></section></div>
</main><script>
(() => {
    'use strict';
    const boot=@json($boot),$=id=>document.getElementById(id);
    let state=null,pending=null,pendingUpload=null,busy=false,available=false;
    try{const saved=JSON.parse(sessionStorage.getItem(boot.storage_key)||'{}');pending=saved.pending||null;pendingUpload=saved.pendingUpload||null;}catch{}
    function persist(){try{sessionStorage.setItem(boot.storage_key,JSON.stringify({pending,pendingUpload}));}catch{}}
    function message(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error);}
    function lock(){for(const id of ['acknowledge','save-update','task-status','note'])$(id).disabled=busy||!available||Boolean(pending);$('retry-update').hidden=!pending;$('retry-update').disabled=busy||!available;$('upload-button').disabled=busy||!available;$('refresh').disabled=busy;}
    async function api(suffix,body){const form=body instanceof FormData;const response=await fetch(boot.base+suffix,{credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,...(form?{}:{'Content-Type':'application/json'})},...(body===undefined?{}:{method:'POST',body:form?body:JSON.stringify(body)})});const out=await response.json().catch(()=>({message:'The server did not confirm the request. Refresh if your browser session expired.'}));if(!response.ok){const error=new Error(out.errors?Object.values(out.errors).flat().join(' '):out.message||'This task link is unavailable.');error.status=response.status;throw error;}return out;}
    function text(parent,tag,value){const node=document.createElement(tag);node.textContent=value;parent.append(node);return node;}
    function render(result){state=result;available=true;$('content').hidden=false;$('title').textContent=result.task.title;$('details').replaceChildren();for(const [label,value] of [['Owner',result.task.owner],['Status',result.task.status],['Next action',result.task.next_action],['Due',result.task.due_on],['Blocker',result.task.blocker||'None recorded'],['Latest note',result.task.note||'No update yet']]){text($('details'),'dt',label);text($('details'),'dd',value);}$('expiry').textContent=`Limited link expires ${result.expires_at}. Version ${result.task.version}.`;$('acknowledged').textContent=result.task.acknowledged_at?`Acknowledged ${result.task.acknowledged_at}. This does not complete the work.`:'Acknowledgment has not been recorded.';$('task-status').value=pending?.status||(['in_progress','awaiting_review'].includes(result.task.status)?result.task.status:'in_progress');$('note').value=pending?.note??result.task.note??'';$('files').replaceChildren();for(const file of result.uploads){const node=document.createElement('article');node.className='file';text(node,'strong',file.name);text(node,'p',`${file.status} · ${file.size} bytes`);if(file.status==='clean'){const a=text(node,'a','Download verified clean file');a.className='button';a.href=boot.base+'/files/'+encodeURIComponent(file.id);a.referrerPolicy='no-referrer';}else{text(node,'p',file.status==='quarantined'?'Stored privately; unavailable until a scanner verifies it clean.':'Download is unavailable.');}$('files').append(node);}if(pending)message('An interrupted update is retained. Retry its exact request before making another change.',true);if(pendingUpload)$('upload-status').textContent=`Interrupted upload: select the same file (${pendingUpload.name}) and retry.`;lock();}
    function denied(error){if([403,404].includes(error.status)){available=false;state=null;$('content').hidden=true;$('details').replaceChildren();$('files').replaceChildren();message('This limited sample link expired, was revoked, or is unavailable. No other work can be accessed.',true);lock();return true;}return false;}
    async function load(){try{render(await api('/data'));}catch(error){if(!denied(error))message(error.message,true);}}
    async function update(action){if(busy||!available)return;pending ||= {request_id:crypto.randomUUID(),expected_version:state.task.version,action,...(action==='update'?{status:$('task-status').value,note:$('note').value}:{})};persist();busy=true;lock();try{const result=await api('/update',pending);pending=null;persist();render(result);message(action==='acknowledge'?'Acknowledgment saved. The sample work remains open.':'Sample update saved.');}catch(error){if(denied(error))return;if(error.status===409&&/sample task changed/i.test(error.message)){pending=null;persist();await load();message('Another device changed the task. Current work is refreshed; review it before drafting a new update.',true);}else message(error.message+' The exact interrupted update is retained for retry.',true);}finally{busy=false;lock();}}
    $('acknowledge').onclick=()=>update('acknowledge');$('update-form').onsubmit=event=>{event.preventDefault();update('update');};$('retry-update').onclick=()=>update(pending.action);$('refresh').onclick=load;
    $('upload-form').onsubmit=async event=>{event.preventDefault();if(busy||!available)return;const file=$('file').files[0];if(!file)return;if(file.size<1||file.size>5242880||!['image/jpeg','image/png','application/pdf'].includes(file.type))return message('Choose a JPEG, PNG or PDF from 1 byte to 5 MB.',true);busy=true;lock();try{const digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(n=>n.toString(16).padStart(2,'0')).join('');const fingerprint=`${file.name}:${file.size}:${file.type}:${digest}`;if(pendingUpload&&pendingUpload.fingerprint!==fingerprint)throw new Error('Select the same interrupted file before starting another upload.');pendingUpload ||= {request_id:crypto.randomUUID(),fingerprint,name:file.name};persist();const form=new FormData();form.append('request_id',pendingUpload.request_id);form.append('file',file);const out=await api('/uploads',form);pendingUpload=null;persist();$('file').value='';$('upload-status').textContent=out.status==='clean'?'File verified clean and attached.':out.status==='quarantined'?'File stored privately and quarantined; download is unavailable until verified clean.':`Upload status: ${out.status}. Download is unavailable.`;await load();}catch(error){if(!denied(error)){$('upload-status').textContent='Upload interrupted. Select the same file to retry its retained request key.';message(error.message,true);}}finally{busy=false;lock();}};
    load();
})();
</script></body></html>
